"use client";

import { useMemo } from "react";
import * as THREE from "three";
import { RoundedBox } from "@react-three/drei";

const BONE = "#f5f5f0";
const INK = "#0a0a0a";
const SIGNAL = "#ff4d00";
const KNIT = "#171715";
const SOLE = "#101010";

/**
 * Abstract performance sneaker sculpted from primitives — side-profile
 * extrusion with rounded bevels, stacked sole, speed fins, collar, laces
 * and a hanging size tag in the accent color.
 */
export default function Shoe() {
  const upperGeo = useMemo(() => {
    const s = new THREE.Shape();
    s.moveTo(-1.95, 0.1);
    s.quadraticCurveTo(-2.14, 0.3, -2.02, 0.62); // heel back
    s.quadraticCurveTo(-1.92, 0.95, -1.52, 0.98); // heel top
    s.quadraticCurveTo(-1.28, 1.0, -1.02, 0.84); // collar dip
    s.quadraticCurveTo(-0.78, 0.7, -0.42, 0.68); // throat
    s.quadraticCurveTo(0.1, 0.62, 0.55, 0.52); // lace slope -> vamp
    s.quadraticCurveTo(1.2, 0.42, 1.66, 0.4); // vamp
    s.quadraticCurveTo(2.04, 0.38, 2.02, 0.2); // toe tip
    s.quadraticCurveTo(1.9, 0.1, 1.55, 0.1); // toe bottom
    s.lineTo(-1.55, 0.1);
    s.quadraticCurveTo(-1.88, 0.1, -1.95, 0.1);

    const geo = new THREE.ExtrudeGeometry(s, {
      depth: 0.98,
      steps: 1,
      curveSegments: 28,
      bevelEnabled: true,
      bevelThickness: 0.17,
      bevelSize: 0.155,
      bevelSegments: 6,
    });
    geo.translate(0, 0, -0.49);
    geo.computeVertexNormals();
    return geo;
  }, []);

  const laces = useMemo(() => {
    const arr: { pos: [number, number, number]; tilt: number }[] = [];
    for (let i = 0; i < 4; i++) {
      const t = i / 3;
      const x = -0.58 + t * 0.86;
      const y = 0.688 - t * 0.115 + 0.085;
      arr.push({ pos: [x, y, 0], tilt: -0.16 });
    }
    return arr;
  }, []);

  return (
    <group rotation={[0, -0.5, 0]}>
      {/* upper */}
      <mesh geometry={upperGeo} castShadow>
        <meshStandardMaterial color={BONE} roughness={0.5} metalness={0.04} />
      </mesh>

      {/* outsole + accent midsole stack */}
      <RoundedBox args={[3.94, 0.2, 1.32]} radius={0.09} position={[-0.01, 0.06, 0]} castShadow>
        <meshStandardMaterial color={SOLE} roughness={0.85} metalness={0.05} />
      </RoundedBox>
      <RoundedBox args={[4.06, 0.13, 1.38]} radius={0.05} position={[0, 0.17, 0]} castShadow>
        <meshStandardMaterial color={SIGNAL} roughness={0.42} metalness={0.08} />
      </RoundedBox>

      {/* heel clip */}
      <RoundedBox args={[0.12, 0.78, 1.3]} radius={0.04} position={[-2.06, 0.52, 0]} rotation={[0, 0, 0.08]} castShadow>
        <meshStandardMaterial color={SIGNAL} roughness={0.4} metalness={0.1} />
      </RoundedBox>

      {/* speed fins — both sides */}
      {[1, -1].map((side) => (
        <group key={side}>
          <RoundedBox
            args={[0.95, 0.07, 0.05]}
            radius={0.02}
            position={[0.18, 0.42, side * 0.66]}
            rotation={[side * 0.12, 0, 0.5]}
          >
            <meshStandardMaterial color={SIGNAL} roughness={0.45} />
          </RoundedBox>
          <RoundedBox
            args={[0.7, 0.07, 0.05]}
            radius={0.02}
            position={[-0.42, 0.55, side * 0.64]}
            rotation={[side * 0.1, 0, 0.5]}
          >
            <meshStandardMaterial color={INK} roughness={0.5} />
          </RoundedBox>
        </group>
      ))}

      {/* collar opening */}
      <mesh position={[-1.02, 0.86, 0]} rotation={[Math.PI / 2, 0, -0.35]}>
        <torusGeometry args={[0.3, 0.09, 12, 40]} />
        <meshStandardMaterial color={KNIT} roughness={0.9} />
      </mesh>
      <mesh position={[-1.0, 0.82, 0]} rotation={[-Math.PI / 2, 0, -0.35]}>
        <circleGeometry args={[0.3, 32]} />
        <meshStandardMaterial color="#050505" roughness={1} />
      </mesh>

      {/* laces */}
      {laces.map((l, i) => (
        <mesh
          key={i}
          position={l.pos}
          rotation={[Math.PI / 2, 0, l.tilt]}
          castShadow
        >
          <capsuleGeometry args={[0.037, 1.0, 6, 16]} />
          <meshStandardMaterial
            color={i === 1 ? SIGNAL : "#111110"}
            roughness={0.55}
          />
        </mesh>
      ))}

      {/* heel pull + hanging size tag */}
      <RoundedBox args={[0.07, 0.26, 0.14]} radius={0.03} position={[-2.02, 1.08, 0]} castShadow>
        <meshStandardMaterial color={SIGNAL} roughness={0.45} />
      </RoundedBox>
      <group position={[-2.1, 0.86, 0.42]} rotation={[0.12, 0.4, 0.12]}>
        <mesh position={[0, -0.12, 0]}>
          <cylinderGeometry args={[0.008, 0.008, 0.26, 8]} />
          <meshStandardMaterial color="#3a3a36" roughness={0.8} />
        </mesh>
        <RoundedBox args={[0.36, 0.24, 0.035]} radius={0.02} position={[0, -0.38, 0]} castShadow>
          <meshStandardMaterial color={SIGNAL} roughness={0.38} metalness={0.12} />
        </RoundedBox>
      </group>
    </group>
  );
}
