"use client";

import { Canvas, useFrame } from "@react-three/fiber";
import {
  ContactShadows,
  Float,
  Grid,
  PresentationControls,
} from "@react-three/drei";
import type { RefObject } from "react";
import Shoe from "./Shoe";

function CameraRig({ scrollRef }: { scrollRef: RefObject<number> }) {
  useFrame((state, delta) => {
    const t = scrollRef.current ?? 0;
    const targetY = 2.2 - t * 1.4;
    const targetZ = 5.6 - t * 0.9;
    state.camera.position.y +=
      (targetY - state.camera.position.y) * Math.min(1, delta * 3);
    state.camera.position.z +=
      (targetZ - state.camera.position.z) * Math.min(1, delta * 3);
    state.camera.lookAt(0, 0.5, 0);
  });
  return null;
}

export default function Scene({ scrollRef }: { scrollRef: RefObject<number> }) {
  return (
    <Canvas
      dpr={[1, 1.75]}
      camera={{ position: [4.4, 2.2, 5.6], fov: 33 }}
      gl={{ antialias: true }}
    >
      <color attach="background" args={["#0a0a0a"]} />
      <fog attach="fog" args={["#0a0a0a", 11, 24]} />

      <ambientLight intensity={0.45} />
      <directionalLight position={[5, 8, 4]} intensity={2.4} color="#ffffff" />
      <directionalLight position={[-6, 3, 2]} intensity={0.7} color="#ffdfc9" />
      <directionalLight position={[-3, 2.5, -6]} intensity={3.2} color="#ff4d00" />

      <PresentationControls
        global
        cursor
        snap={false}
        speed={1.4}
        polar={[-0.32, 0.55]}
        azimuth={[-Infinity, Infinity]}
      >
        <Float
          speed={1.5}
          rotationIntensity={0.14}
          floatIntensity={0.5}
          floatingRange={[-0.05, 0.1]}
        >
          <Shoe />
        </Float>
      </PresentationControls>

      <Grid
        position={[0, -0.06, 0]}
        args={[40, 40]}
        cellSize={0.55}
        cellThickness={0.6}
        cellColor="#1c1c19"
        sectionSize={2.75}
        sectionThickness={1.1}
        sectionColor="#ff4d00"
        fadeDistance={20}
        fadeStrength={2.5}
        infiniteGrid
      />
      <ContactShadows
        position={[0, -0.05, 0]}
        opacity={0.55}
        scale={14}
        blur={2.4}
        far={4}
        color="#000000"
      />

      <CameraRig scrollRef={scrollRef} />
    </Canvas>
  );
}
